import{_ as a,o as r,c as t,ag as o}from"./chunks/framework.CtWPcAmt.js";const m=JSON.parse('{"title":"第 5 章：七款 Agent 的桌面体验","description":"AI Agent 零基础教程","frontmatter":{"title":"第 5 章：七款 Agent 的桌面体验","description":"AI Agent 零基础教程","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"selection/05-overview.md","filePath":"selection/05-overview.md","lastUpdated":null}'),i={name:"selection/05-overview.md"};function l(d,e,n,c,h,s){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第-5-章-七款-agent-的桌面体验" tabindex="-1">第 5 章：七款 Agent 的桌面体验 <a class="header-anchor" href="#第-5-章-七款-agent-的桌面体验" aria-label="Permalink to &quot;第 5 章：七款 Agent 的桌面体验&quot;">​</a></h1><h2 id="页面顺序" tabindex="-1">页面顺序 <a class="header-anchor" href="#页面顺序" aria-label="Permalink to &quot;页面顺序&quot;">​</a></h2><ol><li><a href="/guide/05-claude.html">Claude 桌面版</a></li><li><a href="/guide/05-codex.html">Codex 桌面版</a></li><li><a href="/guide/05-traework.html">TraeWork 中国版</a></li><li><a href="/guide/05-workbuddy.html">WorkBuddy</a></li><li><a href="/guide/05-qoder.html">Qoder 中国版</a></li><li><a href="/guide/05-zcode.html">ZCode 中国版</a></li><li><a href="/guide/05-hermes.html">Hermes Desktop</a></li></ol><h2 id="四类入门分组" tabindex="-1">四类入门分组 <a class="header-anchor" href="#四类入门分组" aria-label="Permalink to &quot;四类入门分组&quot;">​</a></h2><ul><li>海外闭源托管型综合 Agent：Claude、Codex；</li><li>国内综合型 Agent：TraeWork 中国版、WorkBuddy；</li><li>代码优先型 Agent：Qoder 中国版、ZCode 中国版；</li><li>开源自主型 Agent：Hermes Desktop。</li></ul><p>分组只用于帮助新手建立第一印象，不代表能力排名。七款产品必须使用相同结构、共同基准任务和验收口径，最终在第 6 章进行横向选择。</p><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><p>正文已完成（2026-08-13）。七款产品中六款已完成统一基准任务实测（2026-08-12），页面填入版本、订阅、实测数据、六维评分摘要与界面讲解引用；Claude 因账号受限作为阻断案例处理，无性能数据。评分底稿见 <code>docs/12-benchmark-scoring.md</code>，横向选择见 <code>docs/10-selection-matrix.md</code>。</p><h2 id="扩展样本说明" tabindex="-1">扩展样本说明 <a class="header-anchor" href="#扩展样本说明" aria-label="Permalink to &quot;扩展样本说明&quot;">​</a></h2><p>QoderWork CN（0.9.12）已作为第八个扩展样本完成统一基准实测（2 分钟 + 不足 1 分钟两段计费、8.68 Credits / ¥0.34，存在与 Qoder CN 相同的越权读取问题），但未纳入本章正式七款页面——benchmark v1 材料冻结为七款产品。其正式纳入与代码优势任务测试将在 benchmark v2 完成，届时本章升级为八款页面。</p><h2 id="共同测试条件-六款实测产品" tabindex="-1">共同测试条件（六款实测产品） <a class="header-anchor" href="#共同测试条件-六款实测产品" aria-label="Permalink to &quot;共同测试条件（六款实测产品）&quot;">​</a></h2><ul><li>统一任务：使用冻结材料包（input/ 7 份文件），整理 AI Agent 教程材料，生成六个指定交付文件并自检；</li><li>统一验收：6/6 交付、7/7 输入 SHA-256 与基线一致、记录用时/人工介入/权限确认/成本；</li><li>分层呈现：产品托管路径（WorkBuddy、TraeWork、Qoder、Codex）与 BYOK 路径（ZCode、Hermes）分开，Credits/积分/人民币/API 四种成本口径不横比；</li><li>证据：每页结论回指 <code>research/runs/*/run-record.md</code> 与截图；界面讲解见 <code>docs/11-interface-guides/</code>。</li></ul>',12)])])}const g=a(i,[["render",l]]);export{m as __pageData,g as default};
